    "source": "from typing import Optional\n\n\ndef dijkstra_heap(n: int, start: int, adj: list[list[tuple[int, float]]]) -> tuple[list[float], list[int]]:\n    \"\"\"Dijkstra with binary heap — complete Python reference (hand-written heap of (u, d), lazy deletion).\"\"\"\n    INF = float(\"inf\")\n    dist = [INF] * n\n    parent = [-1] * n\n    dist[start] = 0\n    heap: list[tuple[int, float]] = [(start, 0)]\n\n    def push(u: int, d: float) -> None:\n        heap.append((u, d))\n        i = len(heap) - 1\n        while i > 0:\n            p = (i - 1) >> 1\n            if heap[p][1] <= heap[i][1]:\n                break\n            heap[p], heap[i] = heap[i], heap[p]\n            i = p\n\n    def pop() -> Optional[tuple[int, float]]:\n        if not heap:\n            return None\n        top = heap[0]\n        last = heap.pop()\n        if heap:\n            heap[0] = last\n            i = 0\n            while True:\n                l = i * 2 + 1\n                r = l + 1\n                best = i\n                if l < len(heap) and heap[l][1] < heap[best][1]:\n                    best = l\n                if r < len(heap) and heap[r][1] < heap[best][1]:\n                    best = r\n                if best == i:\n                    break\n                heap[i], heap[best] = heap[best], heap[i]\n                i = best\n        return top\n\n    while heap:\n        cur_u, cur_d = pop()\n        if cur_d != dist[cur_u]:\n            continue\n        for v, w in adj[cur_u]:\n            if dist[cur_u] + w < dist[v]:\n                dist[v] = dist[cur_u] + w\n                parent[v] = cur_u\n                push(v, dist[v])\n    return dist, parent\n",
