    "source": "// Dijkstra with binary heap — complete C++17 reference (hand-written heap of (u, d), lazy deletion).\n#include <limits>\n#include <utility>\n#include <vector>\n\nstruct Item { int u; double d; };\n\nstd::pair<std::vector<double>, std::vector<int>> dijkstraHeap(int n, int start, const std::vector<std::vector<std::pair<int, double>>>& adj) {\n    const double INF = std::numeric_limits<double>::infinity();\n    std::vector<double> dist(n, INF);\n    std::vector<int> parent(n, -1);\n    dist[start] = 0;\n    std::vector<Item> heap{{start, 0}};\n    auto push = [&](int u, double d) {\n        heap.push_back({u, d});\n        int i = static_cast<int>(heap.size()) - 1;\n        while (i > 0) {\n            int p = (i - 1) >> 1;\n            if (heap[p].d <= heap[i].d) break;\n            std::swap(heap[p], heap[i]);\n            i = p;\n        }\n    };\n    auto pop = [&]() -> Item {\n        Item top = heap[0];\n        Item last = heap.back();\n        heap.pop_back();\n        if (!heap.empty()) {\n            heap[0] = last;\n            int i = 0;\n            for (;;) {\n                int l = i * 2 + 1;\n                int r = l + 1;\n                int best = i;\n                if (l < static_cast<int>(heap.size()) && heap[l].d < heap[best].d) best = l;\n                if (r < static_cast<int>(heap.size()) && heap[r].d < heap[best].d) best = r;\n                if (best == i) break;\n                std::swap(heap[i], heap[best]);\n                i = best;\n            }\n        }\n        return top;\n    };\n    while (!heap.empty()) {\n        Item cur = pop();\n        if (cur.d != dist[cur.u]) continue;\n        for (auto [v, w] : adj[cur.u]) {\n            if (dist[cur.u] + w < dist[v]) {\n                dist[v] = dist[cur.u] + w;\n                parent[v] = cur.u;\n                push(v, dist[v]);\n            }\n        }\n    }\n    return {dist, parent};\n}\n",
