    "source": "/// Dijkstra with binary heap — complete Rust reference (hand-written heap of (u, d), lazy deletion).\npub fn dijkstra_heap(n: usize, start: usize, adj: &[Vec<(usize, f64)>]) -> (Vec<f64>, Vec<i64>) {\n    fn push(heap: &mut Vec<(usize, f64)>, u: usize, d: f64) {\n        heap.push((u, d));\n        let mut i = heap.len() - 1;\n        while i > 0 {\n            let p = (i - 1) >> 1;\n            if heap[p].1 <= heap[i].1 {\n                break;\n            }\n            heap.swap(p, i);\n            i = p;\n        }\n    }\n    fn pop(heap: &mut Vec<(usize, f64)>) -> Option<(usize, f64)> {\n        if heap.is_empty() {\n            return None;\n        }\n        let top = heap[0];\n        let last = heap.pop().unwrap();\n        if !heap.is_empty() {\n            heap[0] = last;\n            let mut i = 0;\n            loop {\n                let l = i * 2 + 1;\n                let r = l + 1;\n                let mut best = i;\n                if l < heap.len() && heap[l].1 < heap[best].1 { best = l; }\n                if r < heap.len() && heap[r].1 < heap[best].1 { best = r; }\n                if best == i {\n                    break;\n                }\n                heap.swap(i, best);\n                i = best;\n            }\n        }\n        Some(top)\n    }\n    const INF: f64 = f64::INFINITY;\n    let mut dist = vec![INF; n];\n    let mut parent = vec![-1i64; n];\n    dist[start] = 0.0;\n    let mut heap: Vec<(usize, f64)> = vec![(start, 0.0)];\n    while !heap.is_empty() {\n        let (cu, cd) = pop(&mut heap).unwrap();\n        if cd != dist[cu] {\n            continue;\n        }\n        for &(v, w) in &adj[cu] {\n            if dist[cu] + w < dist[v] {\n                dist[v] = dist[cu] + w;\n                parent[v] = cu as i64;\n                push(&mut heap, v, dist[v]);\n            }\n        }\n    }\n    (dist, parent)\n}\n",
