    "source": "package algorithms\n\nimport \"math\"\n\n// Arc is an outgoing edge u→V with weight W (adj[u] lists the arcs of u).\ntype Arc struct {\n\tV int\n\tW float64\n}\n\n// dijkstraHeap — Dijkstra with a hand-written binary heap of (u, d) and lazy deletion.\nfunc dijkstraHeap(n, start int, adj [][]Arc) ([]float64, []int) {\n\ttype item struct {\n\t\tu int\n\t\td float64\n\t}\n\tINF := math.Inf(1)\n\tdist := make([]float64, n)\n\tparent := make([]int, n)\n\tfor i := range dist {\n\t\tdist[i], parent[i] = INF, -1\n\t}\n\tdist[start] = 0\n\theap := []item{{start, 0}}\n\tpush := func(u int, d float64) {\n\t\theap = append(heap, item{u, d})\n\t\ti := len(heap) - 1\n\t\tfor i > 0 {\n\t\t\tp := (i - 1) >> 1\n\t\t\tif heap[p].d <= heap[i].d {\n\t\t\t\tbreak\n\t\t\t}\n\t\t\theap[p], heap[i] = heap[i], heap[p]\n\t\t\ti = p\n\t\t}\n\t}\n\tpop := func() item {\n\t\ttop := heap[0]\n\t\tlast := heap[len(heap)-1]\n\t\theap = heap[:len(heap)-1]\n\t\tif len(heap) > 0 {\n\t\t\theap[0] = last\n\t\t\ti := 0\n\t\t\tfor {\n\t\t\t\tl := i*2 + 1\n\t\t\t\tr := l + 1\n\t\t\t\tbest := i\n\t\t\t\tif l < len(heap) && heap[l].d < heap[best].d {\n\t\t\t\t\tbest = l\n\t\t\t\t}\n\t\t\t\tif r < len(heap) && heap[r].d < heap[best].d {\n\t\t\t\t\tbest = r\n\t\t\t\t}\n\t\t\t\tif best == i {\n\t\t\t\t\tbreak\n\t\t\t\t}\n\t\t\t\theap[i], heap[best] = heap[best], heap[i]\n\t\t\t\ti = best\n\t\t\t}\n\t\t}\n\t\treturn top\n\t}\n\tfor len(heap) > 0 {\n\t\tcur := pop()\n\t\tif cur.d != dist[cur.u] {\n\t\t\tcontinue\n\t\t}\n\t\tfor _, e := range adj[cur.u] {\n\t\t\tif dist[cur.u]+e.W < dist[e.V] {\n\t\t\t\tdist[e.V] = dist[cur.u] + e.W\n\t\t\t\tparent[e.V] = cur.u\n\t\t\t\tpush(e.V, dist[e.V])\n\t\t\t}\n\t\t}\n\t}\n\treturn dist, parent\n}\n",
